function songStatus(text){$('#song-status').textContent=text;$('#save-status').textContent=text;}
function renderSongList(){const q=$('#song-search').value.trim().toLowerCase(),level=$('#song-level').value;const list=stageSongs.filter(s=>(s.name+s.author).toLowerCase().includes(q)&&(level==='全部难度'||s.level===level));$('#stage-song-list').innerHTML=list.length?list.map(s=>`<button class="picker-song ${s.id===selectedSong.id?'selected':''}" data-pick-song="${s.id}"><span class="song-art">${['♪','♩','♫'][s.id%3]}</span><span><b>${s.name}</b><small>${s.author} · ${s.notes.length} 音符</small></span><em>${s.level}</em><span>${s.id===selectedSong.id?'已选择':'＋'}</span></button>`).join(''):'<p class="empty-songs">没有找到这首歌，试试其他关键词。</p>';}
function fitSongKeys(){const base=Math.floor(Math.min(...selectedSong.notes)/12)*12;octave=Math.max(-2,Math.min(2,(base-48)/12));buildKeys();}
