const stageBaseNoteOn=noteOn;noteOn=function(m,source,velocity,settings){const already=active.has(source);stageBaseNoteOn(m,source,velocity,settings);if(already||!active.has(source)||source.startsWith('play')||songMode!=='learn'||songState!=='running')return;songAttempts++;if(m===selectedSong.notes[songIndex]){songHits++;songIndex++;drawSong();if(songIndex===selectedSong.notes.length)completeSongRound();else songStatus(`很好 · ${songIndex} / ${selectedSong.notes.length} 音符`);}else{songStatus('再试一次，跟着高亮琴键。');$('#song-cue-text').textContent=`下一音 ${noteName(selectedSong.notes[songIndex])} · 按 ${labels[selectedSong.notes[songIndex]-(48+octave*12)]}`;}};
